{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "The closest retrieved analogue, tacrolimus, has an absolute oral bioavailability of approximately 20–25% in patients, which meets the F ≥ 20% threshold and supports a high prediction, though it is borderline.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imatinib has a mean absolute bioavailability of 98% in humans, providing strong direct evidence that this chemical space can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "GSK1322322 showed absolute bioavailability of 77% in the fed state and 57% in the fasted state in healthy volunteers, both well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Brepocitinib had an estimated absolute bioavailability of 75% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Brigatinib oral bioavailability was estimated at 46% in healthy volunteers, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Predicted human pharmacokinetics for compound 19 indicated 80% oral bioavailability, supporting high F, although this is a prediction rather than a direct measurement.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues report oral bioavailability at or above the 20% threshold, with most well above it; the closest analogue is borderline but still meets the threshold. Therefore, high bioavailability (F ≥ 20%) is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "The query structure is not provided, limiting structure-based transferability assessment.",
    "All retrieved analogues have low Morgan similarity (<0.4), so transferability is limited.",
    "No retrieved analogue with F < 20% was available to calibrate negative evidence.",
    "The closest analogue, tacrolimus, is borderline at the threshold, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

